@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#172227;--muted:#758287;--line:#e4e9e7;--paper:#f7f8f5;--lime:#c8f169;--deep:#132124;--mono:'DM Mono',monospace;--sans:'DM Sans',system-ui,sans-serif}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#eef1ed;color:var(--ink);font-family:var(--sans);overscroll-behavior:none}body{padding:0}.game-shell{max-width:1440px;margin:auto;padding:0 36px 22px;min-height:100vh;background:#f8f9f6}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none;font-size:15px;font-weight:800;letter-spacing:1.9px;line-height:1}.brand-mark{background:var(--lime);width:35px;height:35px;display:grid;place-items:center;font-size:20px;border-radius:11px;color:#25351f}.brand-sub{display:block;font:9px var(--mono);letter-spacing:1.35px;color:#82908c;margin-top:5px}.world-status{display:flex;align-items:center;gap:10px;font:10px var(--mono);letter-spacing:.7px;color:#53615f}.world-status i,.quick-hint i{height:3px;width:3px;border-radius:50%;background:#a9b5b1}.live-dot{height:7px;width:7px;background:#8fc64b;border-radius:50%;box-shadow:0 0 0 3px #e6f4ce}.icon-btn{width:34px;height:34px;background:transparent;border:1px solid var(--line);border-radius:50%;font-size:16px;color:#566660}.game-layout{display:grid;grid-template-columns:minmax(0,1.72fr) minmax(310px,.82fr);gap:24px;padding-top:24px}.play-column{min-width:0}.game-frame{background:#152528;border:1px solid #263a38;border-radius:10px;overflow:hidden;position:relative;box-shadow:0 16px 38px #1c30201c}.hud-top{height:60px;background:#172a2c;display:flex;align-items:center;justify-content:space-between;padding:0 19px;color:#edf2e8}.pilot-card{display:flex;gap:10px;align-items:center}.pilot-avatar{width:36px;height:36px;background:#283f40;border:1px solid #3b5551;border-radius:9px;display:grid;place-items:center;font-size:21px}.pilot-card b{display:block;font:9px var(--mono);letter-spacing:1px}.pilot-card span{display:block;font:9px var(--mono);color:#92a7a0;margin-top:4px}.pilot-card strong{color:var(--lime)}.pilot-card em{font-style:normal;color:#82938d}.vitals{display:flex;flex-direction:column;gap:6px;width:168px}.vital{display:flex;align-items:center;gap:6px;font:9px var(--mono);color:#f18a7e}.vital .meter{height:5px;background:#344543;border-radius:8px;overflow:hidden;flex:1}.meter i{height:100%;display:block;width:100%;background:#f47769;border-radius:8px;transition:width .25s}.vital b{width:24px;text-align:right;font-weight:400;color:#d9e2d9}.xp-vital{color:var(--lime)}.xp-vital .meter i{background:var(--lime);width:0}.xp-vital b{font-size:8px;width:48px}canvas{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;background:#77926c;image-rendering:pixelated;image-rendering:crisp-edges;touch-action:none}.location-tag{position:absolute;left:14px;top:74px;display:flex;align-items:center;gap:7px;color:#eff4e7;background:#1a302ee0;padding:7px 9px;border:1px solid #ffffff20;border-radius:4px;font:9px var(--mono);letter-spacing:.6px}.location-tag .pin{color:var(--lime);font-size:14px}.coord{color:#93aaa0;border-left:1px solid #57706a;padding-left:7px}.event-toast{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%);background:#152927eF;color:#eaf4db;border:1px solid #c8f16960;border-radius:5px;padding:8px 13px;font:10px var(--mono);letter-spacing:.2px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .2s}.event-toast.show{opacity:1}.frame-bottom{height:31px;background:#172a2c;color:#8da39b;display:flex;align-items:center;justify-content:space-between;padding:0 16px;font:9px var(--mono);letter-spacing:.5px}.frame-bottom b{color:#b7ec61}.frame-bottom strong{color:#d9e7d6;font-weight:400}.frame-bottom i{font-style:normal;color:#51645e}.quickbar{height:64px;border:1px solid var(--line);border-radius:8px;margin-top:11px;background:#fff;display:flex;align-items:center;padding:0 12px;gap:7px}.quick-label{font:9px var(--mono);letter-spacing:1px;color:#8b9994;margin:0 8px 0 3px}.quick-item{position:relative;width:52px;height:50px;border:1px solid transparent;background:#f7f8f4;border-radius:5px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;color:#25312f}.quick-item.selected{border-color:#b8d98a;background:#f5fae8}.quick-item kbd{position:absolute;top:3px;left:4px;font:8px var(--mono);color:#82908a}.quick-item>span{font-size:17px;line-height:18px}.quick-item small{font:7px var(--mono);color:#73817d}.quick-hint{margin-left:auto;font:8px var(--mono);color:#93a09b;letter-spacing:.3px}.side-panel{padding:9px 4px 0;min-width:0;display:flex;flex-direction:column}.panel-heading{display:flex;justify-content:space-between;align-items:center;padding:0 2px 18px}.eyebrow{display:block;font:9px var(--mono);letter-spacing:1.15px;color:#94a19b}.panel-heading h1{font-size:29px;letter-spacing:-1.35px;line-height:1.08;margin:8px 0 0;font-weight:700}.panel-heading h1 span{color:#6e9943}.planet-icon{width:47px;height:47px;border-radius:50%;display:grid;place-items:center;background:#edf5dc;color:#86a84f;font-size:22px;border:1px solid #dfeacb}.objective{display:flex;gap:11px;align-items:center;background:#f0f5e6;border:1px solid #e3ecd6;border-radius:7px;padding:11px;margin-bottom:15px}.objective-icon{width:34px;height:34px;background:#e1edcc;border-radius:6px;display:grid;place-items:center;color:#719743;font-size:19px}.objective b{display:block;font-size:11px;margin-top:4px;font-weight:600}.objective-progress{height:3px;width:100%;background:#dce7ce;border-radius:4px;margin-top:8px}.objective-progress span{display:block;height:100%;width:0;background:#91b852;border-radius:4px;transition:width .3s}.stat-row{display:flex;gap:10px;margin-bottom:18px}.stat{flex:1;padding:9px 10px;border:1px solid var(--line);border-radius:6px;background:#fff}.stat>span{display:block;font:8px var(--mono);color:#899792;letter-spacing:.8px;margin-bottom:6px}.stat b{font:12px var(--mono);color:#293a35}.stat small{font-size:9px;color:#a0aba7;font-weight:400}.section-title{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:1.1px;color:#77857f;margin:0 0 9px}.section-title button{border:0;background:none;color:#809b5c;font:8px var(--mono);letter-spacing:.5px;cursor:pointer}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.item-card{height:54px;background:#fff;border:1px solid var(--line);border-radius:5px;display:flex;align-items:center;padding:6px;gap:6px;min-width:0}.item-emoji{width:25px;height:25px;border-radius:5px;display:grid;place-items:center;background:#f1f4ec;font-size:14px;flex-shrink:0}.item-card b{font:10px var(--mono);display:block}.item-card small{font:7px var(--mono);color:#97a39e;display:block;margin-top:3px;white-space:nowrap}.homestead-title{margin-top:17px}.homestead-title>span:last-child{font-size:8px;color:#ad9b65}.homestead{height:54px;border:1px solid var(--line);border-radius:6px;background:#fff;display:flex;align-items:center;gap:8px;padding:6px}.home-icon{width:36px;height:36px;background:#f1f3eb;border-radius:5px;display:grid;place-items:center;color:#8e9b7a;font-size:21px}.home-copy{min-width:0;flex:1}.home-copy b{font-size:10px;display:block}.home-copy span{font-size:8px;color:#8d9a95;display:block;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.build-btn{background:var(--lime);border:0;border-radius:4px;padding:7px 10px;font:9px var(--mono);color:#283b22;cursor:pointer}.build-btn:disabled{background:#eef0ec;color:#9da7a1}.threat-card{display:flex;gap:9px;align-items:center;margin-top:15px;padding:10px;background:#f8efeb;border:1px solid #f0dfd9;border-radius:6px;position:relative}.threat-icon{width:33px;height:33px;background:#f3dfd8;border-radius:5px;display:grid;place-items:center;font-size:18px;color:#bd705e}.threat-card .eyebrow{font-size:8px;color:#a98b82}.threat-card b{display:block;font-size:10px;margin-top:3px}.threat-card #threatStatus{font-size:8px;color:#a18a82;display:block;margin-top:2px}.threat-pip{margin-left:auto;width:6px;height:6px;background:#d78a73;border-radius:50%;align-self:flex-start;margin-top:4px}.panel-footer{display:flex;justify-content:space-between;margin-top:auto;padding-top:11px;font:8px var(--mono);letter-spacing:.5px;color:#9aa59f}.panel-footer b{color:#738a4c}.bottom-nav{height:53px;margin-top:16px;border-top:1px solid var(--line);display:flex;align-items:center;gap:8px}.bottom-nav button{height:31px;padding:0 11px;background:transparent;border:0;border-radius:5px;color:#91a09a;font:13px var(--mono);cursor:pointer}.bottom-nav button span{font:8px var(--mono);letter-spacing:.6px;margin-left:4px}.bottom-nav button.nav-active{background:#eef4e4;color:#607c3c}.nav-tip{margin-left:auto;color:#99a59f;font:9px var(--mono);font-style:italic}.modal{position:fixed;inset:0;background:#10201dc7;z-index:10;display:grid;place-items:center;padding:20px}.modal.hidden{display:none}.modal-card{position:relative;width:min(470px,100%);background:#f9faf6;border-radius:9px;padding:25px;box-shadow:0 20px 70px #0005}.modal-card h2{font-size:23px;margin:7px 0 15px;letter-spacing:-.7px}.modal-close{position:absolute;right:13px;top:12px;border:0;background:#eef0ea;border-radius:50%;width:28px;height:28px;font-size:19px;color:#68756f;cursor:pointer}.modal-body{font-size:12px;line-height:1.65;color:#64716a}.log-entry{padding:9px 0;border-bottom:1px solid var(--line);display:flex;gap:10px}.log-entry time{font:9px var(--mono);color:#88a35b;white-space:nowrap}.map-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:3px;margin:13px 0}.map-cell{aspect-ratio:1;background:#809873;border-radius:2px;display:grid;place-items:center;font-size:13px}.map-cell:nth-child(7n+2),.map-cell:nth-child(7n+6){background:#6d8567}.map-cell.player{outline:2px solid #d0f275;z-index:1}.modal-action{background:#c8f169;border:0;padding:9px 13px;border-radius:4px;font:10px var(--mono);cursor:pointer;color:#293d20;margin-top:6px}.touch-controls{display:none}.touch-actions{display:none}
@media(max-width:900px){.game-shell{padding:0 18px 14px}.game-layout{grid-template-columns:minmax(0,1.45fr) minmax(280px,.8fr);gap:17px}.quick-hint{font-size:7px}.inventory-grid{grid-template-columns:repeat(2,1fr)}.item-card{height:42px}.side-panel{padding-top:2px}.panel-heading h1{font-size:26px}}
@media(max-width:650px){body{background:#f8f9f6}.game-shell{padding:0 12px 10px}.topbar{height:57px}.brand{font-size:13px}.brand-mark{width:31px;height:31px}.world-status{font-size:8px;gap:7px}.icon-btn{width:30px;height:30px}.game-layout{display:flex;flex-direction:column;gap:12px;padding-top:12px}.game-frame{border-radius:7px}.hud-top{height:49px;padding:0 10px}.pilot-avatar{width:30px;height:30px;font-size:17px}.pilot-card{gap:7px}.pilot-card b{font-size:8px}.pilot-card span{font-size:8px}.vitals{width:126px}.vital{gap:4px}.vital b{font-size:8px}.vital .meter{height:4px}.location-tag{left:8px;top:57px;padding:5px 6px;font-size:7px;gap:4px}.location-tag .pin{font-size:11px}.coord{padding-left:4px;font-size:7px}.frame-bottom{height:26px;padding:0 9px;font-size:7px}.quickbar{height:55px;margin-top:7px;padding:0 7px;gap:3px}.quick-label{font-size:7px;margin:0 3px}.quick-item{height:43px;width:43px}.quick-item>span{font-size:15px}.quick-item small{font-size:6px}.quick-hint{display:none}.side-panel{padding:1px 1px 0;display:grid;grid-template-columns:1fr 1fr;column-gap:9px}.panel-heading{grid-column:1/-1;padding-bottom:11px}.panel-heading h1{font-size:23px;margin-top:5px}.planet-icon{width:38px;height:38px;font-size:18px}.objective{grid-column:1/-1;margin-bottom:9px;padding:8px}.objective-icon{width:30px;height:30px}.objective b{font-size:10px}.stat-row{grid-column:1/-1;margin-bottom:11px}.stat{padding:7px 9px}.section-title{font-size:8px;margin-bottom:6px}.inventory-grid{grid-column:1/-1;grid-template-columns:repeat(4,1fr);gap:4px}.item-card{height:45px;padding:4px;gap:3px;justify-content:center}.item-emoji{width:19px;height:19px;font-size:12px}.item-card b{font-size:9px}.item-card small{font-size:6px}.homestead-title{grid-column:1/-1;margin-top:11px}.homestead{grid-column:1/-1;height:48px}.threat-card{grid-column:1/-1;margin-top:9px;padding:7px}.threat-icon{width:29px;height:29px;font-size:15px}.panel-footer{grid-column:1/-1;margin-top:9px;padding-top:8px}.bottom-nav{height:46px;margin-top:10px;gap:1px;justify-content:space-between}.bottom-nav button{padding:0 6px;font-size:12px}.bottom-nav button span{font-size:7px;margin-left:2px}.nav-tip{display:none}.touch-controls{display:flex;position:absolute;left:10px;right:10px;bottom:39px;justify-content:space-between;align-items:flex-end;pointer-events:none}.dpad{pointer-events:auto;display:flex;flex-direction:column;align-items:center;gap:2px;opacity:.88}.dpad>div{display:flex;gap:2px}.dpad button,.touch-action{width:31px;height:29px;background:#203737d9;border:1px solid #b5c6a755;border-radius:5px;color:#eff6dd;font-size:12px;touch-action:none;user-select:none}.touch-actions{pointer-events:auto;display:flex;gap:6px}.touch-action{width:42px;height:42px;border-radius:50%;font-size:14px;background:#233b37df;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:14px}.touch-action small{font:6px var(--mono);color:#d4e4c1}.event-toast{top:48%;font-size:8px;padding:6px 9px}}
@media(max-width:380px){.world-status{letter-spacing:0}.quick-label{display:none}.vitals{width:110px}.pilot-card em{display:none}.item-card{gap:2px}.home-copy span{font-size:7px}}

(() => {
  'use strict';
  const canvas=document.getElementById('game'), ctx=canvas.getContext('2d');
  ctx.imageSmoothingEnabled=false;
  const W=480,H=270,T=16, WORLD_W=48,WORLD_H=36;
  const $=id=>document.getElementById(id);
  const state={x:12,y:15,level:1,xp:0,hp:100,day:1,hour:8,minute:0,weather:'Clear',season:0,weatherTick:0,wood:4,stone:3,berries:3,seeds:4,fish:0,ore:0,crystals:0,food:4,home:0,rep:0,kills:0,selected:0,dungeon:false,playerDir:'down',attackCd:0,moveCd:0,toastTimer:0,toast:'',log:[],daySeconds:0,plantBeds:[],enemyMemory:0,hasRod:true};
  const seasonNames=['SPRING','SUMMER','AUTUMN','WINTER'], weatherNames=['Clear','Soft rain','Drizzle','Windy','Meteor glow'];
  const toolNames=['PICKAXE','AXE','SEEDS','ROD'];
  const keys={};
  const rnd=(x,y,s=0)=>{let n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n)};
  const trees=[],rocks=[],plants=[],water=[], monsters=[];
  for(let y=2;y<WORLD_H-2;y++)for(let x=2;x<WORLD_W-2;x++){
    const r=rnd(x,y,3);
    if(r>.945 && !(x>7&&x<20&&y>9&&y<22)) trees.push({x,y,hp:3,regrow:0});
    else if(r>.918 && !(x>7&&x<20&&y>9&&y<22)) rocks.push({x,y,hp:2});
    else if(r>.89 && !(x>8&&x<17&&y>12&&y<20)) plants.push({x,y,type:rnd(x,y,8)>.55?'glow':'snap',ready:true,attack:0});
  }
  // River bends along the eastern edge, with a small pond near the camp.
  for(let y=3;y<31;y++){let x=34+Math.round(Math.sin(y*.27)*2); water.push({x,y}); if(y>4&&y<12) water.push({x:x-1,y});}
  for(let y=24;y<27;y++)for(let x=18;x<22;x++)water.push({x,y});
  const bedSpots=[{x:14,y:17},{x:15,y:17},{x:16,y:17},{x:14,y:18},{x:15,y:18},{x:16,y:18}];
  bedSpots.forEach(b=>state.plantBeds.push({...b,planted:0,ready:false}));
  function log(msg){state.log.unshift({day:state.day,text:msg});state.log=state.log.slice(0,14);}
  function notify(msg){state.toast=msg;state.toastTimer=2.4;const el=$('toast');el.textContent=msg;el.classList.add('show');}
  function save(){try{localStorage.setItem('zigga-save',JSON.stringify({...state,trees,rocks,plants,monsters}));$('saveStatus').textContent='AUTO-SAVED';}catch(e){}}
  function load(){try{const d=JSON.parse(localStorage.getItem('zigga-save'));if(!d)return;Object.assign(state,d);['trees','rocks','plants','monsters'].forEach(k=>{if(Array.isArray(d[k])){const target={trees,rocks,plants,monsters}[k];target.splice(0,target.length,...d[k]);}});if(!Array.isArray(state.plantBeds))state.plantBeds=[];}catch(e){}}
  load();
  function addXp(n,why){state.xp+=n;state.rep+=1;let need=levelNeed();while(state.level<75&&state.xp>=need){state.xp-=need;state.level++;state.hp=Math.min(100,state.hp+18);need=levelNeed();notify(`LEVEL UP! You reached level ${state.level}`);log(`Reached level ${state.level}. The wilds are getting stronger.`);}if(why)log(`${why} +${n} XP`);}
  function levelNeed(){return 30+state.level*12;}
  function seasonIndex(){return Math.floor((state.day-1)/28)%4;}
  function monsterLevel(){return Math.max(1,Math.min(70,Math.floor((state.level-1)*.92)+1+Math.min(8,state.kills/8|0)));}
  function nearest(arr,max=1.5){let found=null,best=max;for(const e of arr){if(e.gone||e.hp<=0)continue;const d=Math.hypot(e.x-state.x,e.y-state.y);if(d<best){best=d;found=e;}}return found;}
  function isWater(x,y){return water.some(a=>a.x===x&&a.y===y);}
  function isBlocked(x,y){if(x<1||y<1||x>=WORLD_W-1||y>=WORLD_H-1)return true;if(isWater(x,y))return true;if(trees.some(a=>a.x===x&&a.y===y&&a.hp>0))return true;if(rocks.some(a=>a.x===x&&a.y===y&&a.hp>0))return true;return false;}
  function worldMonsterSpawn(){if(monsters.length>=7)return;let x,y,tries=0;do{x=state.x+Math.round((Math.random()-.5)*18);y=state.y+Math.round((Math.random()-.5)*12);tries++;}while((Math.hypot(x-state.x,y-state.y)<5||isBlocked(x,y)||x<2||y<2||x>=WORLD_W-2||y>=WORLD_H-2)&&tries<20);if(tries<20)monsters.push({x,y,hp:1,level:monsterLevel(),kind:Math.random()>.5?'Mossback':'Thornling',aggro:false,hit:0});}
  function move(dx,dy){if(state.moveCd>0)return;const x=state.x+dx,y=state.y+dy;if(!isBlocked(x,y)){state.x=x;state.y=y;state.playerDir=dx<0?'left':dx>0?'right':dy<0?'up':'down';state.moveCd=.12;}if(state.dungeon)for(const m of monsters){if(Math.hypot(m.x-state.x,m.y-state.y)<5)m.aggro=true;}}
  function useTool(){if(state.dungeon){interactDungeon();return;}const tool=state.selected;
    if(tool===1){const tree=nearest(trees,1.8);if(tree){tree.hp--;if(tree.hp<=0){tree.hp=0;tree.regrow=8;state.wood+=3;addXp(6,'Harvested a moonwood tree.');notify('Moonwood +3 · the stump will regrow');save();}else notify('Chop... one more hit');return;}}
    if(tool===0){const rock=nearest(rocks,1.7);if(rock){rock.hp--;if(rock.hp<=0){rock.hp=0;state.stone+=2;if(Math.random()<.25)state.ore++;addXp(5,'Mined a starstone deposit.');notify('Starstone +2');save();}else notify('Crack! Keep mining');return;}const near=nearest(monsters,1.7);if(near){attack(near);return;}}
    if(tool===2){const bed=bedSpots.find(b=>Math.abs(b.x-state.x)<1.2&&Math.abs(b.y-state.y)<1.2);if(bed){if(bed.planted){if(bed.ready){bed.planted=0;bed.ready=false;state.food+=2;state.seeds++;addXp(8,'Harvested a moonmelon.');notify('Moonmelon harvest +2 food');}else notify('Still growing — give it time');}else if(state.seeds>0){state.seeds--;bed.planted=state.day;bed.ready=false;notify('Seed planted. Rain helps it grow!');addXp(2,'Planted a seed.');}else notify('No seeds left — gather wild plants.');save();return;}notify('Find a garden bed by your camp to plant.');return;}
    if(tool===3){if(isWater(state.x,state.y)||water.some(a=>Math.abs(a.x-state.x)+Math.abs(a.y-state.y)<=1)){if(Math.random()<.68){state.fish++;state.food++;addXp(9,'Caught a skyfin.');notify('Skyfin caught! +1 fish, +1 food');}else{notify('A tug on the line... it got away.');addXp(2,'Went fishing.');}save();return;}notify('Move to the river or pond to fish.');return;}
    interact();
  }
  function interact(){if(state.dungeon){interactDungeon();return;}const plant=nearest(plants,1.65);if(plant){if(plant.type==='snap'&&plant.attack>0){state.hp=Math.max(0,state.hp-8);notify('Snapvine struck!');return;}state.berries+=2;state.seeds++;plant.ready=false;plant.regrow=5;addXp(4,'Foraged from a wild plant.');notify(plant.type==='glow'?'Glowfruit +2 · seeds +1':'Snapvine berries +2');save();return;}
    const bed=bedSpots.find(b=>Math.abs(b.x-state.x)<1.1&&Math.abs(b.y-state.y)<1.1);if(bed){state.selected=2;updateUI();useTool();return;}
    if(Math.hypot(state.x-12,state.y-15)<2&&state.home===0){notify('Build a shelter from the homestead panel.');return;}
